    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h
}

fn tag(h: &mut Harness, tags: Value) {
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": tags}));
}

fn list(h: &mut Harness) -> Value {
    h.ok(json!({"Command": "ListQueueTags", "QueueName": "q"}))["Tags"].clone()
}

#[test]
fn new_queue_has_no_tags_and_tags_replace_and_untag() {
    let mut h = harness_with_queue();
    assert_eq!(list(&mut h), json!({}));
    tag(&mut h, json!({"a": "1", "b": ""}));
    tag(&mut h, json!({"a": "2", "A": "x"}));
    assert_eq!(list(&mut h), json!({"a": "2", "b": "", "A": "x"}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["a", "missing"]}));
    assert_eq!(list(&mut h), json!({"b": "", "A": "x"}));
    tag(&mut h, json!({}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": []}));
    assert_eq!(list(&mut h), json!({"b": "", "A": "x"}));
}

